const procData = $('Procesar Respuesta MVPlay').item.json;

return [{
  json: {
    status: 'created',
    trial_number: procData.trial_number,
    username: procData.username,
    password: procData.password,
    dns: procData.dns,
    dns_smarters: procData.dns_smarters,
    m3u_url: procData.m3u_url,
    instrucciones: procData.instrucciones
  }
}];

return [{
  json: {
    status: 'limit_reached',
    message: 'El cliente ya ha recibido el límite máximo de 2 pruebas gratuitas permitidas.'
  }
}];

const convData = $input.first().json || {};
const contact = convData.meta?.sender || convData.sender || {};
const customAttr = contact.custom_attributes || {};

let triggerItem = {};
try {
  triggerItem = $('Execute Workflow Trigger').first().json || {};
} catch(e) {
  try { triggerItem = $input.first().json || {}; } catch(e2) {}
}

let contact_name = triggerItem.contact_name || triggerItem.name || contact.name || '';
let email = triggerItem.email || contact.email || '';
let phone = (triggerItem.phone || contact.phone_number || '').toString();
const query = (triggerItem.query || '').toString();

if (query) {
  const nameMatch = query.match(/(?:contact_name|nombre|name)\s*:\s*([^,\n]+)/i);
  if (nameMatch && !contact_name) contact_name = nameMatch[1].trim();

  const emailMatch = query.match(/(?:email|correo)\s*:\s*([^,\n\s]+)/i);
  if (emailMatch && !email) email = emailMatch[1].trim();

  const phoneMatch = query.match(/(?:phone|telefono|tel|celular)\s*:\s*([0-9+]+)/i);
  if (phoneMatch && !phone) phone = phoneMatch[1].trim();
}

if (!contact_name) contact_name = 'Cliente';
const fullName = contact_name.trim();

// SEPARATE: TVTotal24 uses ONLY tvtotal_trial_1_id and tvtotal_trial_2_id
const trial1 = customAttr.tvtotal_trial_1_id;
const trial2 = customAttr.tvtotal_trial_2_id;

let trial_number = 1;
let is_limit_reached = false;

if (!trial1) {
  trial_number = 1;
} else if (!trial2) {
  trial_number = 2;
} else {
  trial_number = 3;
  is_limit_reached = true;
}

// Username: NombreApellido (trial 1), NombreApellido2 (trial 2)
let formattedUsername = '';
if (fullName && fullName.toLowerCase() !== 'cliente') {
  const cleanName = fullName
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9\s]/g, '')
    .trim();
  const words = cleanName.split(/\s+/);
  let baseUser = '';
  if (words.length >= 2) {
    baseUser = words[0] + words[1];
  } else if (words.length === 1 && words[0].length >= 3) {
    baseUser = words[0];
  }
  if (baseUser) {
    formattedUsername = trial_number === 2 ? `${baseUser}2` : baseUser;
  }
}

// Password: clean phone number
const cleanPhone = phone.replace(/\D/g, '');
let formattedPassword = cleanPhone;

// Reseller notes: ONLY full name
const resellerNotes = fullName;

const account_id = triggerItem.account_id || 1;
const conversation_id = triggerItem.conversation_id;

return [{
  json: {
    is_limit_reached,
    trial_number,
    contact_name: fullName,
    email: email,
    phone: phone,
    username: formattedUsername,
    password: formattedPassword,
    reseller_notes: resellerNotes,
    account_id,
    conversation_id,
    contact_id: contact.id,
    custom_attributes: customAttr
  }
}];

const resp = $input.first().json || {};
let evalData = {};
try {
  evalData = $('Evaluar Historial y Preparar Datos').first().json || {};
} catch(e) {}

const isSuccess = resp.status === 'STATUS_SUCCESS';
const lineData = resp.data || {};

if (!isSuccess || !lineData.username) {
  throw new Error(`Error de MVPlay al crear línea: ${resp.status || resp.error_code || 'Fallo desconocido'}`);
}

const finalUsername = lineData.username;
const finalPassword = lineData.password;
const lineId = lineData.id;

const updatedCustomAttr = { ...(evalData.custom_attributes || {}) };
const nowIso = new Date().toISOString();

if (evalData.trial_number === 1) {
  updatedCustomAttr.tvtotal_trial_1_id = lineId;
  updatedCustomAttr.tvtotal_trial_1_username = finalUsername;
  updatedCustomAttr.tvtotal_trial_1_password = finalPassword;
  updatedCustomAttr.tvtotal_trial_1_created_at = nowIso;
} else {
  updatedCustomAttr.tvtotal_trial_2_id = lineId;
  updatedCustomAttr.tvtotal_trial_2_username = finalUsername;
  updatedCustomAttr.tvtotal_trial_2_password = finalPassword;
  updatedCustomAttr.tvtotal_trial_2_created_at = nowIso;
}

return [{
  json: {
    is_success: true,
    trial_number: evalData.trial_number,
    username: finalUsername,
    password: finalPassword,
    line_id: lineId,
    account_id: evalData.account_id,
    conversation_id: evalData.conversation_id,
    contact_id: evalData.contact_id,
    custom_attributes: updatedCustomAttr,
    dns: 'http://wk.mvpl.uk:2082',
    dns_smarters: 'http://cdn01link.uk:2095',
    m3u_url: `http://wk.mvpl.uk:2082/get.php?username=${finalUsername}&password=${finalPassword}&type=m3u_plus&output=ts`,
    instrucciones: 'Para Firestick / Android TV / Móviles Android: Abre la app TotalTV, selecciona el panel TOTALTV LATINA e introduce tu usuario y contraseña. Para Smart TV / Apple: Usa Smarters Player Lite con el DNS para Smarters (http://cdn01link.uk:2095)'
  }
}];

const procData = $('Procesar Respuesta MVPlay').item.json;
const conversation_id = procData.conversation_id;
const account_id = procData.account_id || 1;
const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = `https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/${account_id}`;

try {
  const getRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${chatwootBase}/conversations/${conversation_id}/labels`,
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  const currentLabels = getRes.payload || [];
  // Remove any prior stage-* label (e.g. stage-lead-entrantes, stage-contactado, etc.)
  const cleanedLabels = currentLabels.filter(label => !label.startsWith('stage-'));
  cleanedLabels.push('stage-fase-de-pruebas');

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${chatwootBase}/conversations/${conversation_id}/labels`,
    headers: {
      'api_access_token': chatwootToken,
      'Content-Type': 'application/json'
    },
    body: { labels: cleanedLabels },
    json: true
  });
} catch (e) {}

return $input.all();

const triggerItem = $('Execute Workflow Trigger').first().json || {};
const convData = $('Obtener Conversacion Chatwoot').first().json || {};
const contact = convData.meta?.sender || convData.sender || {};

let fullName = triggerItem.contact_name || triggerItem.name || contact.name || 'Cliente';
fullName = fullName.trim();
const words = fullName.split(/\s+/).filter(Boolean);
const nombre = words.length > 0 ? words[0] : 'Cliente';
const apellidos = words.length > 1 ? words.slice(1).join(' ') : '';

const email = triggerItem.email || contact.email || '';
const phone = (triggerItem.phone || contact.phone_number || '').toString().replace(/\D/g, '');
const contacto = contact.name || fullName;
const conversation_id = String(triggerItem.conversation_id || $('Procesar Respuesta MVPlay').first().json.conversation_id || '');

const now = new Date();
const timestamp = now.toISOString().replace('T', ' ').substring(0, 19);

return [{
  json: {
    Nombre: nombre,
    Apellidos: apellidos,
    Email: email,
    Telefono: phone,
    Timestamp: timestamp,
    Contacto: contacto,
    'Conversation ID': conversation_id
  }
}];

